import numpy as np
from PIL import Image
x=np.load('source_pixels.npz')['rgb']
# ascii frame0 and temporal diff to f20, every 2 pixels, region 45:130,25:120
chars=' .:-=+*#%@'
for mode in ['lum','darkgreen','diff5','diff20','diff50']:
 print('\\n',mode)
 for y in range(25,121,2):
  s=''
  for xx in range(45,131,2):
   p=x[0,y:y+2,xx:xx+2].mean((0,1))
   if mode=='lum': v=p.mean()
   elif mode=='darkgreen': v=255-(p[1]-p[0]+p[1]-p[2]+100)
   else:
    t=int(mode[4:]); v=np.abs(x[t,y:y+2,xx:xx+2].astype(int)-x[0,y:y+2,xx:xx+2]).max(2).mean()
   if mode.startswith('diff'): idx=min(9,int(v/12))
   else: idx=min(9,max(0,int(v/256*10)))
   s+=chars[idx]
  print(s)
PY"

